// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');
const loadInter = makeLoadFont('Inter');

const { fontFamily: robotoMono } = loadRobotoMono();
const { fontFamily: inter } = loadInter();



export type PasswordTypingProps = Record<string, any>;

const charSet = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*";

const PasswordTyping: React.FC<PasswordTypingProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 5,
  passwordLength = 14,
  typingSpeed = 4,
  labelText = "Administrator Password",
  primaryColor = "#3b82f6",
  textColor = "#f8fafc",
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const startDelay = 30;
  const typingDuration = passwordLength * typingSpeed;

  const entrance = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const isTyping = frame >= startDelay && frame <= startDelay + typingDuration;
  const cursorBlink = Math.floor(frame / 15) % 2 === 0 ? 1 : 0;
  const cursorOpacity = isTyping ? 1 : cursorBlink;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: inter,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          width: 800,
          transform: `scale(${entrance}) translateY(${interpolate(
            entrance,
            [0, 1],
            [50, 0]
          )}px)`,
          transition: "none",
        }}
      >
        <h2
          style={{
            margin: 0,
            marginBottom: 16,
            color: textColor,
            fontSize: 24,
            fontWeight: 500,
            opacity: 0.9,
            transition: "none",
          }}
        >
          {labelText}
        </h2>

        <div
          style={{
            width: "100%",
            height: 100,
            backgroundColor: "rgba(0,0,0,0.3)",
            border: `2px solid rgba(255,255,255,0.15)`,
            borderRadius: 0,
            display: "flex",
            flexDirection: "row",
            alignItems: "center",
            padding: "0 32px",
            boxSizing: "border-box",
            transition: "none",
          }}
        >
          {Array.from({ length: passwordLength }).map((_, i) => {
            const charAppearsAt = startDelay + i * typingSpeed;
            const timeSinceTyped = frame - charAppearsAt;
            const isVisible = timeSinceTyped >= 0;

            if (!isVisible) return null;

            const nextCharAppearsAt = startDelay + (i + 1) * typingSpeed;
            const isMasked =
              timeSinceTyped >= 12 ||
              (i < passwordLength - 1 && frame >= nextCharAppearsAt);

            const charIndex = Math.floor(random(`char-${i}`) * charSet.length);
            const randomChar = charSet[charIndex];

            const itemScale = spring({
              frame: timeSinceTyped,
              fps,
              config: { damping: 12, mass: 0.5 },
            });

            return (
              <div
                key={i}
                style={{
                  width: 24,
                  display: "flex",
                  justifyContent: "center",
                  alignItems: "center",
                  transform: `scale(${itemScale})`,
                  transition: "none",
                }}
              >
                {isMasked ? (
                  <div
                    style={{
                      width: 16,
                      height: 16,
                      borderRadius: 8,
                      backgroundColor: textColor,
                      transition: "none",
                    }}
                  />
                ) : (
                  <span
                    style={{
                      fontFamily: robotoMono,
                      fontSize: 48,
                      color: textColor,
                      transition: "none",
                    }}
                  >
                    {randomChar}
                  </span>
                )}
              </div>
            );
          })}

          <div
            style={{
              width: 4,
              height: 56,
              backgroundColor: primaryColor,
              marginLeft: 8,
              opacity: cursorOpacity,
              borderRadius: 0,
              transition: "none",
            }}
          />
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PasswordTyping;